struct CaseLess {
  bool operator()(const std::string& a, const std::string& b) const {
    auto lower = [](unsigned char c) { return std::tolower(c); };
    return std::ranges::lexicographical_compare(a, b, {}, lower, lower);
  }
};

int main() {
  std::set<std::string, CaseLess> s{"Apple"};
